{
  "name": "HP 3488A 开关控制单元",
  "name_en": "HP 3488A Switch/Control Unit",
  "manufacturer": "Hewlett-Packard",
  "description": "一款可编程模块化开关控制主机，可安装不同类型的开关卡或继电器卡，在自动化测试与测量系统中用于信号切换、通道复用和仪器/被测件之间的连接路由。",
  "description_en": "A programmable modular switch/control mainframe that accepts different switch or relay cards and is used in automated test and measurement systems for signal switching, channel multiplexing, and routing connections between instruments and devices under test.",
  "tag_hints": [
    "switch matrix",
    "signal routing",
    "automated test equipment",
    "relay switching",
    "modular mainframe",
    "instrument switching"
  ],
  "actions": [
    {
      "action_name": "auto-switch",
      "description": "切换指定开关通道的开/关状态。",
      "description_en": "Open or close a specified switch channel."
    },
    {
      "action_name": "auto-viewtext",
      "description": "查看指定开关通道的文本状态信息。",
      "description_en": "View the textual status information for a specified switch channel."
    },
    {
      "action_name": "auto-view",
      "description": "查看指定开关通道的状态。",
      "description_en": "Query the state of a specified switch channel."
    },
    {
      "action_name": "auto-cards",
      "description": "查看已安装的开关卡或模块。",
      "description_en": "List the installed switch cards or modules."
    },
    {
      "action_name": "auto-switches",
      "description": "列出可用的开关通道。",
      "description_en": "List the available switch channels."
    },
    {
      "action_name": "auto-state",
      "description": "查看全部开关通道的状态。",
      "description_en": "Query the states of all switch channels."
    }
  ]
}

